use std::path::PathBuf;

use harness::Harness;

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut mode = String::from("all");
    let mut sizes = String::from("200,1000");
    let mut samples = 8_usize;
    let mut kd = std::env::var("KD_BIN").unwrap_or_else(|_| "target/release/kd".to_string());
    let mut no_idle = false;
    let mut json_out: Option<PathBuf> = None;
    let mut md_out: Option<PathBuf> = None;
    let mut quality_md: Option<PathBuf> = None;
    let mut quality_json: Option<PathBuf> = None;

    let mut index = 0;
    while index < args.len() {
        let arg = args[index].as_str();
        let next = |index: &mut usize| -> String {
            *index += 1;
            args.get(*index).cloned().unwrap_or_default()
        };
        match arg {
            "micro" | "e2e" | "all" | "quality" | "sweep" | "custo" => mode = arg.to_string(),
            "--sizes" => sizes = next(&mut index),
            "--samples" => samples = next(&mut index).parse().unwrap_or(samples),
            "--kd" => kd = next(&mut index),
            "--no-idle" => no_idle = true,
            "--json" => json_out = Some(PathBuf::from(next(&mut index))),
            "--out" => md_out = Some(PathBuf::from(next(&mut index))),
            "--quality-out" => quality_md = Some(PathBuf::from(next(&mut index))),
            "--quality-json" => quality_json = Some(PathBuf::from(next(&mut index))),
            "--quick" => {
                sizes = "200".to_string();
                samples = 5;
            }
            "--help" | "-h" => {
                println!(
                    "uso: knudge-bench [micro|e2e|quality|sweep|custo|all] [--sizes 200,1000] [--samples 8] [--kd PATH] [--json out.json] [--out report.md] [--quality-out bench/qualidade.md] [--quality-json bench/qualidade.json] [--quick]"
                );
                return;
            }
            other => {
                eprintln!("argumento desconhecido: {other}");
                std::process::exit(2);
            }
        }
        index += 1;
    }

    let sizes: Vec<usize> = sizes
        .split(',')
        .filter_map(|part| part.trim().parse().ok())
        .collect();
    let sizes = if sizes.is_empty() {
        vec![200, 1000]
    } else {
        sizes
    };

    let mut harness = Harness::new();
    if mode == "micro" || mode == "all" {
        eprintln!("== micromb (sizes={sizes:?}) ==");
        micro::run(&mut harness, &sizes);
    }
    let kd_path = PathBuf::from(&kd);
    let absolute = if kd_path.is_absolute() {
        kd_path
    } else {
        std::env::current_dir().unwrap_or_default().join(kd_path)
    };
    if mode == "e2e" || mode == "all" {
        eprintln!(
            "== ponta-a-ponta (kd={}, sizes={sizes:?}) ==",
            absolute.display()
        );
        e2e::run(&mut harness, &absolute, &sizes, samples, no_idle);
    }
    if mode == "custo" || mode == "all" {
        eprintln!("== custo por resposta (kd={}) ==", absolute.display());
        custo::run(&absolute);
    }
    if mode == "quality" || mode == "all" {
        eprintln!("== qualidade de retrieval ==");
        let md = quality_md.unwrap_or_else(|| PathBuf::from("bench/qualidade.md"));
        let json = quality_json.unwrap_or_else(|| PathBuf::from("bench/qualidade.json"));
        quality::run(&md, &json);
    }
    if mode == "sweep" {
        eprintln!("== sweep da fusão (E16/T09) ==");
        quality::sweep();
    }

    if mode == "micro" || mode == "e2e" || mode == "all" {
        let markdown = harness.render_markdown();
        print!("{markdown}");
        if let Some(path) = md_out {
            let _ = std::fs::write(path, &markdown);
        }
        if let Some(path) = json_out {
            let _ = std::fs::write(path, harness.render_json());
        }
    }
